class myDataset(Dataset):
    def __init__(self, array, labels):
        self.array = array
        self.label = labels

    def __getitem__(self, index):
        data = self.array[index].to(torch.float32)
        label = self.label[index].long()
        return data, label

    def __len__(self):
        return len(self.array)
